    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> money(n);
    for (int i = 0; i < n; i++) cin >> money[i];

    long long take = 0, skip = 0;
    for (long long x : money) {
        long long newTake = skip + x;
        skip = max(skip, take);
        take = newTake;
    }
    cout << max(take, skip) << "\n";

